import{_ as r,o as e,c as t,a2 as i}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"上线检查清单","description":"上线检查清单：灵萌 运维保障官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"ops/checklist.md","filePath":"ops/checklist.md","lastUpdated":1785020677000}'),o={name:"ops/checklist.md"};function l(n,a,s,h,d,g){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="上线检查清单" tabindex="-1">上线检查清单 <a class="header-anchor" href="#上线检查清单" aria-label="Permalink to &quot;上线检查清单&quot;">​</a></h1><p>面向 <strong>站点管理员</strong> 的上线前核对项，帮助您确认安全、微信与备份等关键事项已就绪。技术细节可交给运维，您负责在后台逐项确认。</p><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>提供一份可勾选的上线前检查列表，降低漏配微信回调、默认弱密码等常见风险。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>站点已完成 <a href="/guide/quick-start">快速部署</a> 与 <a href="/guide/setup-wizard">初始化向导</a>。</li><li>您拥有超级管理员或具备系统配置权限的管理员账号。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>请登录管理后台，按下列分组逐项确认（可在 printed 清单上打勾）。</p><h3 id="一、基础信息" tabindex="-1">一、基础信息 <a class="header-anchor" href="#一、基础信息" aria-label="Permalink to &quot;一、基础信息&quot;">​</a></h3><ul><li>[ ] <strong>系统设置 → 网站信息</strong> 中域名为正式 <strong>HTTPS</strong> 地址，与用户访问一致（<a href="/config/site-info">网站信息</a>）</li><li>[ ] <strong>系统设置 → 我的模块</strong> 已核对开通项（<a href="/config/my-modules">我的模块</a>）</li><li>[ ] <strong>系统设置 → 系统配置 → 区域配置</strong> 中区域模式符合运营计划（单区域 / 多区域）</li><li>[ ] <strong>区域管理 → 区域列表</strong> 已创建目标运营区域（<a href="/config/region">区域管理</a>）</li><li>[ ] <strong>UI管理 → 页面配置 / TabBar</strong> 首页与底部导航已启用（<a href="/features/ui-editor/">UI 编辑器</a>）</li></ul><h3 id="二、安全-管理员必查" tabindex="-1">二、安全（管理员必查） <a class="header-anchor" href="#二、安全-管理员必查" aria-label="Permalink to &quot;二、安全（管理员必查）&quot;">​</a></h3><ul><li>[ ] 默认账号 <code>admin</code> 已 <strong>修改强密码</strong> 或重建超管</li><li>[ ] 生产环境 <strong>不存在万能验证码</strong>（由运维确认服务器配置中验证码主码为空）</li><li>[ ] <strong>系统设置 → 账号权限</strong> 已为每位管理员分配最小必要权限（未授权默认不可访问；见 <a href="/config/admin-permissions">账号权限</a>）</li><li>[ ] 建议超管启用 <strong>二次验证（MFA）</strong></li></ul><h3 id="三、微信与支付" tabindex="-1">三、微信与支付 <a class="header-anchor" href="#三、微信与支付" aria-label="Permalink to &quot;三、微信与支付&quot;">​</a></h3><ul><li>[ ] <strong>系统配置 → 微信小程序 / 微信公众号</strong> Token 测试通过（见 <a href="/features/wechat">微信</a>）</li><li>[ ] <strong>区域管理 → 用户配置</strong> 已按需开启微信登录（<a href="/config/user-rules">用户规则</a>）</li><li>[ ] <strong>系统配置 → 微信支付</strong> 证书与密钥已填（<a href="/features/wechat-pay">微信支付完整手册</a>）</li><li>[ ] 微信商户平台支付回调 URL 已设为：<code>https://你的域名/api/payment/wx-notify</code></li><li>[ ] 若用支付宝，开放平台回调 URL 已设为：<code>https://你的域名/api/payment/alipay-notify</code></li><li>[ ] 已完成 <strong>0.01 元</strong> 测试支付与一笔测试提现（如启用；<a href="/features/finance">财务</a>）</li></ul><h3 id="四、内容与合规" tabindex="-1">四、内容与合规 <a class="header-anchor" href="#四、内容与合规" aria-label="Permalink to &quot;四、内容与合规&quot;">​</a></h3><ul><li>[ ] <strong>系统设置 → 全局违禁词</strong> 已启用检测并导入基础词库（<a href="/config/forbidden-words">违禁词</a>）</li><li>[ ] <strong>区域管理 → 笔记配置</strong> 审核策略符合要求（<a href="/features/circle-note">圈子与笔记</a>）</li><li>[ ] 用户协议、隐私政策链接在 <strong>UI管理 → 页面配置</strong> 或 <strong>网站信息</strong> 中可访问</li><li>[ ] <strong>通知控制台 → 事件模板</strong> 渠道勾选符合预期（<a href="/features/notification">通知</a>）</li></ul><h3 id="五、备份与运维交接" tabindex="-1">五、备份与运维交接 <a class="header-anchor" href="#五、备份与运维交接" aria-label="Permalink to &quot;五、备份与运维交接&quot;">​</a></h3><ul><li>[ ] 已约定 <strong>数据库每日备份</strong> 方案（由运维执行，您确认备份任务存在）</li><li>[ ] 知晓 <strong>系统监控 → 系统状态 / 服务健康中心</strong> 入口（见 <a href="/ops/monitoring">系统监控</a>）</li><li>[ ] 可选搜索 / 推荐 Docker 栈若启用，密钥非默认值（见 <a href="/ops/docker-infra">可选基础设施</a>）</li></ul><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>上线前每个 <strong>对外运营区域</strong> 至少确认：</p><ul><li>[ ] <strong>用户配置</strong> 登录方式、验证码策略</li><li>[ ] <strong>笔记配置</strong> 发布与审核规则</li><li>[ ] 已开通业务的区域配置（外卖 / 跑腿 / 闲置 / 推广等）</li></ul><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><p>完成清单后，用 <strong>真实用户路径</strong> 冒烟：</p><ol><li>注册 → 登录 → 发笔记 → 搜索</li><li>微信登录 + 小额支付（如启用）</li><li>管理后台 <strong>系统监控 → 系统状态</strong> 无红色关键项</li><li><code>/setup</code> 初始化页面对外不可访问（由运维确认）</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>清单项不知道谁负责</strong></p><ul><li>带「服务器 / 环境变量 / 备份」的交给运维；带菜单路径的由管理员在后台完成。</li></ul><p><strong>微信都配了仍无法支付</strong></p><ul><li>单独走 <a href="/features/payment">支付</a> 文档「验证是否生效」一节。</li></ul><p><strong>上线后想回滚</strong></p><ul><li>保留上一版部署与数据库备份；联系运维执行回滚，管理员暂停活动入口。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/wechat">微信</a></li><li><a href="/features/payment">支付与提现</a></li><li><a href="/ops/monitoring">系统监控入口</a></li><li><a href="/ops/faq">常见问题</a></li></ul>',33)])])}const f=r(o,[["render",l]]);export{u as __pageData,f as default};
